      "newContent": "package com.acme.shortener.qr;

import com.acme.shortener.config.ShortenerProperties;
import com.acme.shortener.link.Link;
import com.acme.shortener.link.LinkNotFoundException;
import com.acme.shortener.link.LinkRepository;
import org.springframework.stereotype.Service;

/**
 * QR codes for active links. The status comes from the database, not the redirect cache, so a
 * deleted link stops getting QR codes at once (the cache is not evicted on delete yet). The code
 * carries the short URL, never the original URL: scans go through the redirect and are counted.
 */
@Service
public class QrCodeService {

  public static final int DEFAULT_SIZE = 256;
  public static final int MIN_SIZE = 128;
  public static final int MAX_SIZE = 1024;

  private final LinkRepository links;
  private final QrCodeEncoder encoder;
  private final String baseUrl;

  public QrCodeService(
      LinkRepository links, QrCodeEncoder encoder, ShortenerProperties properties) {
    this.links = links;
    this.encoder = encoder;
    String base = properties.baseUrl();
    this.baseUrl = base.endsWith("/") ? base.substring(0, base.length() - 1) : base;
  }

  /**
   * @param size pixels per side; {@code null} means {@link #DEFAULT_SIZE}
   */
  public byte[] png(String code, Integer size) {
    int pixels = size == null ? DEFAULT_SIZE : size;
    if (pixels < MIN_SIZE || pixels > MAX_SIZE) {
      throw new InvalidQrSizeException(pixels, MIN_SIZE, MAX_SIZE);
    }
    Link link =
        links
            .findByCode(code)
            .filter(Link::isActive)
            .orElseThrow(() -> new LinkNotFoundException(code));
    return encoder.png(baseUrl + "/" + link.code(), pixels);
  }
}
